 'Forêt ancienne':()=>sky('#6f9a6a','#cfe0b8','lb11')+`<g opacity=".5">${[0,1,2,3].map(i=>`<path d="M${140+i*50} 0 L${100+i*60} 230 L${130+i*60} 230Z" fill="#fff6c8"><animate attributeName="opacity" values=".3;.7;.3" dur="${5+i}s" repeatCount="indefinite"/></path>`).join('')}</g>`+[[30,26,'#4a3524'],[110,40,'#5b4228'],[230,34,'#4a3524'],[330,46,'#5b4228']].map(([x,w,c])=>`<path d="M${x} 230 L${x+6} 0 L${x+w-6} 0 L${x+w} 230Z" fill="${c}"/><path d="M${x+w*.3} 40 v150 M${x+w*.65} 20 v190" stroke="#3a2a1c" stroke-width="2"/>`).join('')+`<g fill="#2f5a34">${[0,1,2,3,4,5].map(i=>`<circle cx="${i*80}" cy="${10+(i%2)*14}" r="60"/>`).join('')}</g><rect y="200" width="400" height="30" fill="#4f7a3a"/><g>${[[90,206],[200,210],[300,204]].map(([x,y])=>`<rect x="${x-1.5}" y="${y-6}" width="3" height="8" fill="#f6efe0"/><path d="M${x-7} ${y-6} a7 5 0 0 1 14 0Z" fill="#c8432e"/><circle cx="${x-2}" cy="${y-8}" r="1.2" fill="#fff"/>`).join('')}</g>`,
