export function landmarkArt(name,fallback=''){const f=ART[name];if(!f)return fallback;return `<svg viewBox="0 0 400 230" role="img" aria-label="${name}" preserveAspectRatio="xMidYMid slice">${f()}</svg>`;}
export const LANDMARK_ART_NAMES=Object.keys(ART);
